  6	final class TopologicalSort {
  7	
  8	    private static final int SAMPLE_VERTEX_COUNT = 6;
  9	    private static final Edge[] SAMPLE_EDGES = {
 10	        edge(0, 1),
 11	        edge(1, 2),
 12	        edge(2, 3),
 13	        edge(4, 5),
 14	        edge(5, 1),
 15	        edge(5, 2)
 16	    };
 17	
 18	    private TopologicalSort() {
 19	    }
 20	
 21	    private static final class Edge {
 22	        private final int from;
 23	        private final int to;
 24	
 25	        private Edge(int from, int to) {
 26	            this.from = from;
 27	            this.to = to;
 28	        }
 29	    }
 30	
 31	    static List<Integer> topoSort(List<? extends List<Integer>> adjacencyList) {
 32	        return topologicalSort(adjacencyList);
 33	    }
 34	
 35	    static List<Integer> topologicalSort(List<? extends List<Integer>> adjacencyList) {
 36	        int vertexCount = adjacencyList.size();
 37	        int[] inDegree = calculateInDegrees(adjacencyList);
 38	        Deque<Integer> readyVertices = collectZeroInDegreeVertices(inDegree);
 39	        List<Integer> sortedVertices = new ArrayList<>(vertexCount);
 40	
 41	        while (!readyVertices.isEmpty()) {
 42	            int vertex = readyVertices.removeFirst();
 43	            sortedVertices.add(vertex);
 44	            enqueueReadyNeighbors(adjacencyList.get(vertex), inDegree, readyVertices);
 45	        }
 46	
 47	        return sortedVertices;
 48	    }
 49	
 50	    static void addEdge(List<? extends List<Integer>> adjacencyList, int from, int to) {
 51	        adjacencyList.get(from).add(to);
 52	    }
 53	
 54	    private static Edge edge(int from, int to) {
 55	        return new Edge(from, to);
 56	    }
 57	
 58	    private static List<List<Integer>> buildSampleGraph() {
 59	        return buildGraph(SAMPLE_VERTEX_COUNT, SAMPLE_EDGES);
 60	    }
 61	
 62	    private static List<List<Integer>> buildGraph(int vertexCount, Edge[] edges) {
 63	        List<List<Integer>> adjacencyList = createEmptyAdjacencyList(vertexCount);
 64	        for (Edge edge : edges) {
 65	            addEdge(adjacencyList, edge.from, edge.to);
 66	        }
 67	        return adjacencyList;
 68	    }
 69	
 70	    private static int[] calculateInDegrees(List<? extends List<Integer>> adjacencyList) {
 71	        int[] inDegree = new int[adjacencyList.size()];
 72	        for (List<Integer> neighbors : adjacencyList) {
 73	            for (int next : neighbors) {
 74	                inDegree[next]++;
 75	            }
 76	        }
 77	        return inDegree;
 78	    }
 79	
 80	    private static Deque<Integer> collectZeroInDegreeVertices(int[] inDegree) {
 81	        Deque<Integer> readyVertices = new ArrayDeque<>();
 82	        for (int vertex = 0; vertex < inDegree.length; vertex++) {
 83	            if (inDegree[vertex] == 0) {
 84	                readyVertices.addLast(vertex);
 85	            }
 86	        }
 87	        return readyVertices;
 88	    }
 89	
 90	    private static void enqueueReadyNeighbors(
 91	            List<Integer> neighbors,
 92	            int[] inDegree,
 93	            Deque<Integer> readyVertices
 94	    ) {
 95	        for (int next : neighbors) {
 96	            inDegree[next]--;
 97	            if (inDegree[next] == 0) {
 98	                readyVertices.addLast(next);
 99	            }
100	        }
101	    }
102	
103	    private static List<List<Integer>> createEmptyAdjacencyList(int vertexCount) {
104	        List<List<Integer>> adjacencyList = new ArrayList<>(vertexCount);
105	        for (int vertex = 0; vertex < vertexCount; vertex++) {
106	            adjacencyList.add(new ArrayList<>());
107	        }
108	        return adjacencyList;
109	    }
110	
111	    private static void printVertices(List<Integer> vertices) {
112	        System.out.println(formatVertices(vertices));
113	    }
114	
115	    private static String formatVertices(List<Integer> vertices) {
116	        StringBuilder output = new StringBuilder();
117	        for (int vertex : vertices) {
118	            output.append(vertex).append(' ');
119	        }
120	        return output.toString();
121	    }
122	
123	    public static void main(String[] args) {
124	        List<List<Integer>> adjacencyList = buildSampleGraph();
125	        List<Integer> sortedVertices = topologicalSort(adjacencyList);
126	        printVertices(sortedVertices);
127	    }
128	}

